def can_split(nums, m, limit):
    parts, cur = 1, 0
    for x in nums:
        if cur + x > limit:
            parts += 1
            cur = x
            if parts > m:
                return False
        else:
            cur += x
    return True

def split_array(nums, m):
    lo, hi = max(nums), sum(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if can_split(nums, m, mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

