class Node:
    def __init__(self, val, nxt=None):
        self.val = val
        self.next = nxt

def find_middle(vals):
    dummy = Node(0)
    cur = dummy
    for v in vals:
        cur.next = Node(v)
        cur = cur.next
    slow = fast = dummy.next
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
    return slow.val

